type Remote<T> =
  | { status: "loading" }
  | { status: "success"; data: T }
  | { status: "error"; message: string };
function describe(value: Remote<string[]>): string {
  switch (value.status) {
    case "loading": return "Loading";
    case "success": return value.data.length + " lessons";
    case "error": return value.message;
  }
}
// TypeScript snippet: describe({status:"success",data:[]}) gives "0 lessons".

type Row = {id:string; title:string; done:boolean};
type Action = {type:"toggle"; id:string} | {type:"remove"; id:string};
function reducer(state: Row[], action: Action): Row[] {
  switch (action.type) {
    case "toggle": return state.map(row => row.id === action.id ? {...row, done:!row.done} : row);
    case "remove": return state.filter(row => row.id !== action.id);
  }
}
// Component fragment: const [rows, dispatch] = useReducer(reducer, []);

